    'arena.d_acct_failed': { en: 'Your paper account can’t load right now ({reason}).', hi: 'आपका पेपर अकाउंट अभी लोड नहीं हो सकता ({reason})।', it: 'Il tuo conto simulato non si carica in questo momento ({reason}).', es: 'Tu cuenta en papel no se puede cargar ahora mismo ({reason}).', zh: '你的模擬帳戶目前無法載入（{reason}）。', pt: 'A sua conta em papel não consegue carregar neste momento ({reason}).', fr: 'Votre compte papier ne peut pas se charger pour l’instant ({reason}).', de: 'Dein Paper-Konto lässt sich gerade nicht laden ({reason}).', nl: 'Je papieren account kan nu niet laden ({reason}).', ja: 'ペーパー口座を今は読み込めません（{reason}）。', ko: '지금은 모의 계정을 불러올 수 없습니다({reason}).', ru: 'Сейчас не удаётся загрузить ваш бумажный счёт ({reason}).', tr: 'Kâğıt hesabınız şu anda yüklenemiyor ({reason}).', ar: 'تعذّر تحميل حسابك الورقي الآن ({reason}).' },
