    'dp.crossyield': { en: 'Worth moving? — cross-chain yield planner', hi: 'स्थानांतरित करना फ़ायदेमंद है? — क्रॉस-चेन यील्ड प्लानर', it: 'Vale la pena spostare? — pianificatore di rendimento cross-chain', es: '¿Vale la pena mover? — planificador de rendimiento entre cadenas', zh: '值得搬家嗎？——跨鏈收益規劃', pt: 'Vale a pena mover? — planejador de rendimento entre cadeias', fr: 'Vaut-il de déplacer ? — planificateur de rendement cross-chain', ar: 'هل يستحق النقل؟ — مخطط العوائد عبر السلاسل', de: 'Lohnt ein Umzug? — Cross-Chain-Renditeplaner', nl: 'Verhuizen waard? — cross-chain rendementsplanner', ja: '移す価値は？ — クロスチェーン利回りプランナー', ko: '옮길 가치가 있을까? — 크로스체인 수익 플래너', ru: 'Стоит ли переводить? — планировщик кросс-чейн доходности', tr: 'Taşımaya değer mi? — zincirler arası getiri planlayıcı' },
