    'dd.e_positions': { en: 'No open positions. The Trade view has a full order ticket.', hi: 'कोई खुली position नहीं। Trade व्यू में पूरा ऑर्डर टिकट मौजूद है।', it: 'Nessuna posizione aperta. La vista Opera contiene un ordine completo.', es: 'Sin posiciones abiertas. La vista Trade tiene una boleta completa.', zh: '目前沒有持倉。交易頁面有完整的下單單據。', pt: 'Sem posições abertas. A view Trade tem uma boleta completa.', fr: 'Aucune position ouverte. La vue Trade contient un ticket complet.', ar: 'لا توجد مراكز مفتوحة. تحتوي صفحة التداول على تذكرة أمر كاملة.', de: 'Keine offenen Positionen. Im Trade-Bereich findest du ein vollständiges Orderticket.', nl: 'Geen open posities. In het Handel-scherm vind je een volledig orderticket.', ja: '保有ポジションはありません。取引画面に完全な注文チケットがあります。', ko: '보유 포지션이 없습니다. 거래 화면에 전체 주문 티켓이 있습니다.', ru: 'Открытых позиций нет. Во вкладке «Торговля» есть полный ордерный тикет.', tr: 'Açık pozisyon yok. İşlem sekmesinde tam bir emir formu var.' },
    'dd.e_signals': { en: 'No signals yet — they appear as the engine scans.', hi: 'अभी कोई signal नहीं — engine के स्कैन करते ही ये दिखने लगेंगे।', it: 'Ancora nessun segnale — compaiono man mano che il motore analizza.', es: 'Aún no hay señales — aparecen mientras el motor escanea.', zh: '尚無訊號——引擎掃描時會出現。', pt: 'Ainda sem sinais — aparecem conforme o motor varre.', fr: 'Pas encore de signaux — ils apparaissent au fil des scans.', ar: 'لا إشارات بعد — تظهر أثناء مسح المحرك.', de: 'Noch keine Signale — sie erscheinen, während die Engine scannt.', nl: 'Nog geen signalen — ze verschijnen terwijl de motor scant.', ja: 'シグナルはまだありません — エンジンのスキャンとともに表示されます。', ko: '아직 신호가 없습니다 — 엔진이 스캔하면서 나타납니다.', ru: 'Сигналов пока нет — они появятся по мере сканирования движком.', tr: 'Henüz sinyal yok — motor taradıkça görünecekler.' },
    'dd.e_macro': { en: 'The macro backdrop appears once market data is available.', hi: 'मार्केट डेटा उपलब्ध होते ही macro पृष्ठभूमि दिखाई देगी।', it: 'Il contesto macro compare quando ci sono dati di mercato.', es: 'El contexto macro aparece cuando hay datos de mercado.', zh: '市場數據可用後即顯示宏觀背景。', pt: 'O pano de fundo macro aparece quando houver dados de mercado.', fr: 'Le contexte macro apparaît dès que les données de marché arrivent.', ar: 'تظهر الخلفية الكلية عند توفر بيانات السوق.', de: 'Der Makro-Hintergrund erscheint, sobald Marktdaten verfügbar sind.', nl: 'De macro-achtergrond verschijnt zodra er marktdata is.', ja: '市場データが利用可能になるとマクロ背景が表示されます。', ko: '시장 데이터가 준비되면 매크로 배경이 표시됩니다.', ru: 'Макро-фон появится, как только будут доступны рыночные данные.', tr: 'Makro arka plan, piyasa verisi geldiğinde görünür.' },
    'dd.e_agent': { en: 'Agent status unavailable right now.', hi: 'agent की स्थिति अभी उपलब्ध नहीं है।', it: 'Stato dell’agente non disponibile al momento.', es: 'Estado del agente no disponible ahora.', zh: '代理狀態目前無法取得。', pt: 'Status do agente indisponível agora.', fr: 'Statut de l\'agent indisponible pour le moment.', ar: 'حالة الوكيل غير متاحة حاليًا.', de: 'Agentenstatus derzeit nicht verfügbar.', nl: 'Agentstatus momenteel niet beschikbaar.', ja: 'エージェントの状態は現在取得できません。', ko: '에이전트 상태를 현재 확인할 수 없습니다.', ru: 'Статус агента сейчас недоступен.', tr: 'Ajan durumu şu anda kullanılamıyor.' },
    'dd.e_letter': { en: 'The first letter writes itself after the first full week of recorded activity.', hi: 'दर्ज गतिविधि के पहले पूरे सप्ताह के बाद पहला पत्र अपने आप लिखा जाता है।', it: 'La prima lettera si scrive da sé dopo la prima settimana completa di attività registrata.', es: 'La primera carta se escribe sola tras la primera semana completa de actividad registrada.', zh: '第一封信會在完整記錄一週活動後自動生成。', pt: 'A primeira carta se escreve após a primeira semana completa de atividade registrada.', fr: 'La première lettre s\'écrit après une première semaine complète d\'activité enregistrée.', ar: 'تُكتب الرسالة الأولى بعد أول أسبوع كامل من النشاط المسجَّل.', de: 'Der erste Brief schreibt sich nach der ersten vollen Woche aufgezeichneter Aktivität.', nl: 'De eerste brief schrijft zichzelf na de eerste volledige week met vastgelegde activiteit.', ja: '最初のレターは、記録された活動が丸1週間そろった後に自動で書かれます。', ko: '첫 레터는 기록된 활동이 한 주를 채운 뒤 자동으로 작성됩니다.', ru: 'Первое письмо напишется само после первой полной недели записанной активности.', tr: 'İlk mektup, kaydedilen ilk tam haftadan sonra kendiliğinden yazılır.' },
