    'acc.link_social': { en: 'Link social accounts', hi: 'सोशल खाते लिंक करें', it: 'Collega account social', es: 'Vincular cuentas sociales', zh: '連結社群帳號', pt: 'Ligar contas sociais', fr: 'Lier des comptes sociaux', de: 'Social-Konten verknüpfen', nl: 'Sociale accounts koppelen', ja: 'ソーシャルアカウントを連携', ko: '소셜 계정 연동', ru: 'Привязать соцсети', tr: 'Sosyal hesapları bağla', ar: 'ربط حسابات التواصل' },
    'acc.link_social_body': { en: 'Connect another way to sign in. You’ll stay the same account.', hi: 'साइन इन करने का एक और तरीका जोड़ें। आपका खाता वही रहेगा।', it: 'Collega un altro modo per accedere. Resterai sempre lo stesso account.', es: 'Conecta otra forma de iniciar sesión. Seguirás siendo la misma cuenta.', zh: '連接另一種登入方式。你的帳戶維持不變。', pt: 'Ligue outra forma de iniciar sessão. Continuará a ser a mesma conta.', fr: 'Ajoutez un autre moyen de vous connecter. Vous restez le même compte.', de: 'Verbinde einen weiteren Anmeldeweg. Es bleibt dasselbe Konto.', nl: 'Koppel een andere manier om in te loggen. Je blijft hetzelfde account.', ja: '別のログイン方法を追加します。アカウントは同じままです。', ko: '다른 로그인 방법을 연결합니다. 계정은 그대로 유지됩니다.', ru: 'Добавьте другой способ входа. Аккаунт останется тем же.', tr: 'Başka bir giriş yöntemi bağlayın. Hesabınız aynı kalır.', ar: 'أضف طريقة أخرى لتسجيل الدخول. سيبقى الحساب نفسه.' },
    'acc.verify_text': { en: 'Your email isn’t verified yet.', hi: 'आपका ईमेल अभी सत्यापित नहीं है।', it: 'La tua email non è ancora verificata.', es: 'Tu correo aún no está verificado.', zh: '你的電子郵件尚未驗證。', pt: 'O seu email ainda não foi verificado.', fr: 'Votre e-mail n’est pas encore vérifié.', de: 'Deine E-Mail ist noch nicht bestätigt.', nl: 'Je e-mailadres is nog niet geverifieerd.', ja: 'メールアドレスはまだ確認されていません。', ko: '이메일이 아직 인증되지 않았습니다.', ru: 'Ваша почта ещё не подтверждена.', tr: 'E-postanız henüz doğrulanmadı.', ar: 'لم يتم التحقق من بريدك الإلكتروني بعد.' },
    'acc.resend_verify': { en: 'Resend verification email', hi: 'सत्यापन ईमेल दोबारा भेजें', it: 'Reinvia l’email di verifica', es: 'Reenviar correo de verificación', zh: '重新寄送驗證信', pt: 'Reenviar email de verificação', fr: 'Renvoyer l’e-mail de vérification', de: 'Bestätigungsmail erneut senden', nl: 'Verificatiemail opnieuw sturen', ja: '確認メールを再送信', ko: '인증 메일 다시 보내기', ru: 'Отправить письмо ещё раз', tr: 'Doğrulama e-postasını yeniden gönder', ar: 'إعادة إرسال بريد التحقق' },
    'acc.wallet': { en: 'Wallet', hi: 'Wallet', it: 'Wallet', es: 'Cartera', zh: '錢包', pt: 'Carteira', fr: 'Portefeuille', de: 'Wallet', nl: 'Wallet', ja: 'ウォレット', ko: '지갑', ru: 'Кошелёк', tr: 'Cüzdan', ar: 'المحفظة' },
    'acc.wallet_body': { en: 'Link a browser wallet to mirror your on-chain balances and DeFi positions — read-only: the wallet signs one login message, never a transaction.', hi: 'अपने on-chain बैलेंस और DeFi पोज़िशन को मिरर करने के लिए एक ब्राउज़र wallet लिंक करें — read-only (केवल-पठन): wallet केवल एक login संदेश पर हस्ताक्षर करता है, किसी लेनदेन पर कभी नहीं।', it: 'Collega un wallet del browser per rispecchiare i tuoi saldi on-chain e le posizioni DeFi — in sola lettura: il wallet firma un messaggio di accesso, mai una transazione.', es: 'Vincula una cartera del navegador para reflejar tus saldos on-chain y posiciones DeFi — solo lectura: la cartera firma un mensaje de inicio de sesión, nunca una transacción.', zh: '連結瀏覽器錢包以鏡射你的鏈上餘額與 DeFi 部位 — 唯讀：錢包只簽署一則登入訊息，絕不簽署交易。', pt: 'Ligue uma carteira do navegador para espelhar os seus saldos on-chain e posições DeFi — apenas leitura: a carteira assina uma mensagem de início de sessão, nunca uma transação.', fr: 'Liez un portefeuille de navigateur pour refléter vos soldes on-chain et vos positions DeFi — lecture seule : le portefeuille signe un message de connexion, jamais une transaction.', de: 'Verknüpfe eine Browser-Wallet, um deine On-Chain-Guthaben und DeFi-Positionen zu spiegeln — nur lesend: Die Wallet signiert eine Login-Nachricht, niemals eine Transaktion.', nl: 'Koppel een browserwallet om je on-chain saldi en DeFi-posities te spiegelen — alleen-lezen: de wallet ondertekent één inlogbericht, nooit een transactie.', ja: 'ブラウザウォレットを連携すると、オンチェーン残高と DeFi ポジションをミラーできます — 読み取り専用で、ウォレットが署名するのはログインメッセージのみ、取引に署名することはありません。', ko: '브라우저 지갑을 연결하면 온체인 잔고와 DeFi 포지션을 그대로 볼 수 있습니다 — 읽기 전용이며, 지갑은 로그인 메시지 하나에만 서명하고 트랜잭션에는 결코 서명하지 않습니다.', ru: 'Привяжите браузерный кошелёк, чтобы отражать он-чейн балансы и DeFi-позиции — только чтение: кошелёк подписывает одно сообщение входа и никогда транзакцию.', tr: 'Zincir üstü bakiyelerinizi ve DeFi pozisyonlarınızı yansıtmak için bir tarayıcı cüzdanı bağlayın — salt okunur: cüzdan yalnızca bir giriş mesajı imzalar, asla bir işlem imzalamaz.', ar: 'اربط محفظة متصفح لعكس أرصدتك على السلسلة ومراكز DeFi — للقراءة فقط: توقّع المحفظة رسالة تسجيل دخول واحدة، ولا توقّع معاملة أبدًا.' },
