    'dd.w_step_sign': { en: 'Sign the login message in {wallet} — this is not a transaction.', hi: '{wallet} में लॉगिन मैसेज साइन करें — यह कोई ट्रांज़ैक्शन नहीं है।', it: 'Firma il messaggio di accesso in {wallet} — non è una transazione.', es: 'Firma el mensaje de acceso en {wallet} — no es una transacción.', zh: '在 {wallet} 中簽署登入訊息 — 這不是交易。', pt: 'Assine a mensagem de início de sessão em {wallet} — não é uma transação.', fr: 'Signez le message de connexion dans {wallet} — ce n’est pas une transaction.', de: 'Signiere die Login-Nachricht in {wallet} — das ist keine Transaktion.', nl: 'Teken het inlogbericht in {wallet} — dit is geen transactie.', ja: '{wallet}でログインメッセージに署名してください — これは取引ではありません。', ko: '{wallet}에서 로그인 메시지에 서명하세요 — 거래가 아닙니다.', ru: 'Подпишите сообщение входа в {wallet} — это не транзакция.', tr: '{wallet} içinde giriş mesajını imzalayın — bu bir işlem değildir.', ar: 'وقّع رسالة الدخول في {wallet} — هذه ليست معاملة.' },
