    'fw.t.homoglyph': { en: 'Mixed-script (homoglyph) characters', hi: 'मिश्रित-स्क्रिप्ट (होमोग्लिफ़) वर्ण', it: 'Caratteri a script misto (omoglifi)', es: 'Caracteres de escritura mixta (homóglifos)', zh: '混合字集（同形異字）字元', pt: 'Carateres de escrita mista (homóglifos)', fr: 'Caractères à écritures mixtes (homoglyphes)', de: 'Zeichen gemischter Schriften (Homoglyphen)', nl: 'Tekens uit gemengde schriften (homoglyfen)', ja: '複数字体の混在（同形異字）文字', ko: '혼합 문자 체계(호모글리프) 문자', ru: 'Символы смешанных алфавитов (гомоглифы)', tr: 'Karışık yazı sistemi (homoglif) karakterleri', ar: 'محارف بخطوط مختلطة (متشابهة الشكل)' },
    'fw.t.url_http': { en: 'Insecure http:// link', hi: 'असुरक्षित http:// लिंक', it: 'Link http:// non sicuro', es: 'Enlace http:// inseguro', zh: '不安全的 http:// 連結', pt: 'Ligação http:// insegura', fr: 'Lien http:// non sécurisé', de: 'Unsicherer http://-Link', nl: 'Onveilige http://-link', ja: '安全でない http:// リンク', ko: '안전하지 않은 http:// 링크', ru: 'Небезопасная ссылка http://', tr: 'Güvensiz http:// bağlantısı', ar: 'رابط http:// غير آمن' },
