    'venue.queued': { en: 'Queued — the bot applies it within a minute.', hi: 'क्यू में — bot इसे एक मिनट के भीतर लागू कर देगा।', it: 'In coda — il bot la applica entro un minuto.', es: 'En cola — el bot la aplica en menos de un minuto.', zh: '已排入佇列 — 機器人會在一分鐘內套用。', pt: 'Em fila — o bot aplica-a dentro de um minuto.', fr: 'En file — le bot l’applique en moins d’une minute.', de: 'In der Warteschlange — der Bot wendet sie binnen einer Minute an.', nl: 'In de wachtrij — de bot past het binnen een minuut toe.', ja: 'キューに追加しました — ボットが 1 分以内に適用します。', ko: '대기열에 추가됨 — 봇이 1분 이내에 적용합니다.', ru: 'В очереди — бот применит в течение минуты.', tr: 'Sıraya alındı — bot bir dakika içinde uygular.', ar: 'في الطابور — سيطبّقه البوت خلال دقيقة.' },
